  nl: { lang: "nl", locale: "nl_NL" },
  da: { lang: "da", locale: "da_DK" },
  se: { lang: "sv", locale: "sv_SE" },
  pt: { lang: "pt", locale: "pt_PT" },
  cz: { lang: "cs", locale: "cs_CZ" },
  fi: { lang: "fi", locale: "fi_FI" },
  gr: { lang: "el", locale: "el_GR" },
